{
  "name": "docuseal",
  "version": "1.0.6",
  "description": "DocuSeal CLI — manage esignature templates, submissions, and submitters from the terminal",
  "type": "module",
  "homepage": "https://www.docuseal.com",
  "author": "DocuSeal <support@docuseal.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/docusealco/docuseal-cli.git"
  },
  "bin": {
    "docuseal": "bin/run.js"
  },
  "scripts": {
    "dev": "node src/index.js",
    "build": "esbuild src/index.js --bundle --outfile=dist/index.js --platform=node --format=esm --packages=external",
    "test": "node --test tests/*.test.js",
    "prepublishOnly": "npm test && npm run build"
  },
  "files": [
    "dist",
    "bin",
    "skills"
  ],
  "keywords": [
    "docuseal",
    "cli",
    "esign",
    "pdf",
    "signing",
    "documents"
  ],
  "license": "MIT",
  "devDependencies": {
    "esbuild": "^0.27.4"
  },
  "dependencies": {
    "@docuseal/api": "^1.0.24",
    "commander": "^13.0.0",
    "qs": "^6.15.0"
  }
}

import { DocusealApi, DocusealApiError } from '@docuseal/api'
import { loadConfig } from './config.js'
import { renderJson } from './output.js'
import pkg from '../../package.json' with { type: 'json' }

export { DocusealApi, DocusealApiError }

export function createClient(opts = {}) {
  const overrides = {}

  if (opts.apiKey) overrides.apiKey = opts.apiKey
  if (opts.server) overrides.server = opts.server

  const config = loadConfig(Object.keys(overrides).length > 0 ? overrides : undefined)

  return new DocusealApi({ key: config.apiKey, url: config.server, userAgent: `DocuSeal CLI v${pkg.version}` })
}

export function onError(err) {
  if (err instanceof DocusealApiError) {
    const match = err.message.match(/^HTTP Error: \d+ - (.*)$/s)

    if (match) {
      try { renderJson(JSON.parse(match[1])) } catch { renderJson({ error: match[1] }) }
    } else {
      renderJson({ error: err.message })
    }

    process.exit(1)
  }

  throw err
}

import { createServer } from 'node:http'
import { execFile } from 'node:child_process'
import { writeFileSync, unlinkSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { describe, test, before, after, beforeEach } from 'node:test'
import assert from 'node:assert/strict'

let server, port, lastRequest

before(async () => {
  server = createServer((req, res) => {
    let body = ''
    req.on('data', (chunk) => body += chunk)
    req.on('end', () => {
      lastRequest = {
        method: req.method,
        path: req.url.split('?')[0].replace('/api', ''),
        query: Object.fromEntries(new URL(req.url, 'http://localhost').searchParams),
        headers: req.headers,
        body: body ? JSON.parse(body) : undefined,
      }
      res.writeHead(200, { 'Content-Type': 'application/json' })
      res.end(JSON.stringify({ id: 1 }))
    })
  })
  await new Promise(resolve => server.listen(0, resolve))
  port = server.address().port
})

after(() => server.close())
beforeEach(() => { lastRequest = null })

function cli(...args) {
  return new Promise((resolve) => {
    execFile('node', [join(import.meta.dirname, '..', 'src', 'index.js'), ...args], {
      env: {
        ...process.env,
        DOCUSEAL_API_KEY: 'test-key',
        DOCUSEAL_SERVER: `http://localhost:${port}/api`,
      },
    }, (err, stdout, stderr) => {
      resolve({ stdout, stderr, code: err?.code ?? 0 })
    })
  })
}

// --- templates list ---

describe('templates list', () => {
  test('no flags', async () => {
    await cli('templates', 'list')
    assert.equal(lastRequest.method, 'GET')
    assert.equal(lastRequest.path, '/templates')
  })

  test('--q', async () => {
    await cli('templates', 'list', '--q', 'NDA')
    assert.equal(lastRequest.query.q, 'NDA')
  })

  test('--slug', async () => {
    await cli('templates', 'list', '--slug', 'abc123')
    assert.equal(lastRequest.query.slug, 'abc123')
  })

  test('--external-id', async () => {
    await cli('templates', 'list', '--external-id', 'ext-1')
    assert.equal(lastRequest.query.external_id, 'ext-1')
  })

  test('--folder', async () => {
    await cli('templates', 'list', '--folder', 'Legal')
    assert.equal(lastRequest.query.folder, 'Legal')
  })

  test('--archived', async () => {
    await cli('templates', 'list', '--archived')
    assert.equal(lastRequest.query.archived, 'true')
  })

  test('--limit and --after', async () => {
    await cli('templates', 'list', '--limit', '25', '--after', '100')
    assert.equal(lastRequest.query.limit, '25')
    assert.equal(lastRequest.query.after, '100')
  })

  test('--before', async () => {
    await cli('templates', 'list', '--before', '50')
    assert.equal(lastRequest.query.before, '50')
  })

  test('multiple flags combined', async () => {
    await cli('templates', 'list', '--folder', 'HR', '--q', 'offer', '--limit', '5')
    assert.equal(lastRequest.query.folder, 'HR')
    assert.equal(lastRequest.query.q, 'offer')
    assert.equal(lastRequest.query.limit, '5')
  })
})

