export function renderJson(data) {
  console.log(JSON.stringify(data, null, 2))
}

export function renderSuccess(message, details) {
  console.log('✓ ' + message)
  if (details) {
    for (const [key, value] of Object.entries(details)) {
      console.log(`  ${key}: ${value}`)
    }
  }
}

export function renderError(message, hint) {
  console.log('✗ ' + message)
  if (hint) console.log(`\n  ${hint}`)
}

import { parse } from 'qs'
import { readFileSync, existsSync } from 'fs'
import { basename } from 'path'

export function parseDataFlags(pairs) {
  const jsonPairs = pairs.filter(p => p.startsWith('{'))
  const qsPairs = pairs.filter(p => !p.startsWith('{')).map(encodePair)

  let result = qsPairs.length > 0 ? parse(qsPairs.join('&'), { depth: 10, arrayLimit: Infinity }) : {}

  for (const json of jsonPairs) {
    result = deepMerge(result, JSON.parse(json))
  }

  return resolveFiles(result)
}

function encodePair(pair) {
  const bracketEqualsPos = pair.indexOf(']=')
  const pos = bracketEqualsPos === -1 ? pair.indexOf('=') : bracketEqualsPos + 1

  if (pos === -1) return encodeURIComponent(pair)

  return encodeURIComponent(pair.slice(0, pos)) + '=' + encodeURIComponent(pair.slice(pos + 1))
}

function resolveFiles(obj) {
  if (Array.isArray(obj)) {
    obj.forEach(item => resolveFiles(item))
  } else if (obj && typeof obj === 'object') {
    if (typeof obj.file === 'string' && !/^https?:\/\//.test(obj.file)) {
      if (existsSync(obj.file)) {
        obj.name = obj.name || basename(obj.file)
        obj.file = Buffer.from(readFileSync(obj.file)).toString('base64')
      } else if (/^\S+\.[A-Za-z0-9]{1,8}$/.test(obj.file)) {
        throw new Error(`File not found: ${obj.file}`)
      }
    }

    for (const val of Object.values(obj)) {
      resolveFiles(val)
    }
  }

  return obj
}

export function deepMerge(target, source) {
  for (const key of Object.keys(source)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue
    if (Array.isArray(source[key]) && Array.isArray(target[key])) {
      for (let i = 0; i < source[key].length; i++) {
        if (source[key][i] !== undefined) {
          if (typeof source[key][i] === 'object' && typeof target[key][i] === 'object') {
            target[key][i] = deepMerge(target[key][i], source[key][i])
          } else {
            target[key][i] = source[key][i]
          }
        }
      }
    } else if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key]) &&
               target[key] && typeof target[key] === 'object' && !Array.isArray(target[key])) {
      target[key] = deepMerge(target[key], source[key])
    } else {
      target[key] = source[key]
    }
  }
  return target
}

import { existsSync, mkdirSync, readFileSync, writeFileSync, chmodSync } from 'fs'
import { homedir } from 'os'
import { join } from 'path'

function getConfigDir() {
  if (process.env.XDG_CONFIG_HOME) {
    return join(process.env.XDG_CONFIG_HOME, 'docuseal')
  } else if (process.platform === 'win32' && process.env.APPDATA) {
    return join(process.env.APPDATA, 'docuseal')
  } else {
    return join(homedir(), '.config', 'docuseal')
  }
}

const CONFIG_DIR = getConfigDir()
const CONFIG_FILE = join(CONFIG_DIR, 'credentials.json')

const SERVER_MAP = {
  global: 'https://api.docuseal.com',
  europe: 'https://api.docuseal.eu',
}

export function resolveServer(input) {
  if (SERVER_MAP[input]) return SERVER_MAP[input]

  const url = input.replace(/\/+$/, '')

  if (Object.values(SERVER_MAP).includes(url)) return url

  return url.endsWith('/api') ? url : url + '/api'
}

export function loadConfig(overrides) {
  let fileConfig = {}
  if (existsSync(CONFIG_FILE)) {
    fileConfig = JSON.parse(readFileSync(CONFIG_FILE, 'utf8'))
  }

  const apiKey =
    overrides?.apiKey ??
    process.env.DOCUSEAL_API_KEY ??
    fileConfig.apiKey

  const server = resolveServer(
    overrides?.server ??
    process.env.DOCUSEAL_SERVER ??
    fileConfig.server ??
    'global'
  )

  if (!apiKey) {
    throw new Error(
      'No API key found.\nRun `docuseal configure` or set the DOCUSEAL_API_KEY environment variable.'
    )
  }

  return { apiKey, server }
}

export function saveConfig(config) {
  if (!existsSync(CONFIG_DIR)) mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 })

  writeFileSync(CONFIG_FILE, JSON.stringify(config, null, 2) + '\n', { mode: 0o600 })
  chmodSync(CONFIG_FILE, 0o600)
}

import { createInterface } from 'readline'
import { DocusealApi } from '@docuseal/api'
import { loadConfig, saveConfig, resolveServer } from '../lib/config.js'
import { renderSuccess, renderError } from '../lib/output.js'
import { formatExamples } from '../lib/global-options.js'

export function registerConfigure(program) {
  program
    .command('configure')
    .description('Configure API key and server')
    .option('--api-key <value>', 'API key to save')
    .option('--server <value>', 'Server: global, europe, or full URL (default: global)')
    .option('--list', 'Show current configuration and verify authentication')
    .addHelpText('afterAll', formatExamples([
      'docuseal configure',
      'docuseal configure --api-key YOUR_KEY --server global',
      'docuseal configure --list',
    ]))
    .action(async (opts) => {
      if (opts.list) {
        try {
          const config = loadConfig()
          const masked = config.apiKey.slice(0, 8) + '...' + config.apiKey.slice(-4)
          renderSuccess('Current configuration', { api_key: masked, server: config.server })
        } catch (err) {
          renderError(err.message)
          process.exit(1)
        }
        return
      }

      let apiKey = opts.apiKey
      let server = opts.server

      if (!apiKey || !server) {
        const rl = createInterface({ input: process.stdin, output: process.stdout })

        const ask = (q) =>
          new Promise(resolve => rl.question(q, resolve))

        if (!server) {
          server = (await ask('Server [global | europe | https://docuseal.yourdomain.com] (default: global):')) || 'global'
        }

        if (!apiKey) {
          apiKey = await ask('Enter your API token: ')
        }

        rl.close()
      }

      const resolvedServer = resolveServer(server)

      try {
        const client = new DocusealApi({ key: apiKey, url: resolvedServer })
        await client.listSubmissions({ limit: 1 })
      } catch {
        renderError('Invalid API key')
        process.exit(1)
      }

      saveConfig({ apiKey, server: resolvedServer })
      renderSuccess('Saved to ~/.config/docuseal/credentials.json')
    })
}

import { Option } from 'commander'

export function withGlobalOptions(cmd) {
  return cmd
    .addOption(new Option('--api-key <value>').hideHelp())
    .addOption(new Option('--server <value>').hideHelp())
    .addHelpText('afterAll', '\nGlobal Options:\n  --api-key <value>   Override API key for this invocation\n  --server <value>    Server: global, europe, or full URL (e.g. https://docuseal.yourdomain.com)')
}

export function formatDataParams(params) {
  const maxLen = Math.max(...params.map(([k]) => k.length))
  const lines = params.map(([k, v]) => `  ${k.padEnd(maxLen + 2)}${v}`)
  return '\nData Parameters (-d):\n' + lines.join('\n')
}

export function formatExamples(examples) {
  return '\nExamples:\n' + examples.map(e => `  $ ${e}`).join('\n')
}
